-- ===== 账号、会话与一次性授权凭据 =====
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) UNIQUE, password_hash VARCHAR(100), nickname VARCHAR(40) NOT NULL,
 bio VARCHAR(500) NOT NULL DEFAULT '', role ENUM('user','admin') NOT NULL DEFAULT 'user', status ENUM('active','disabled') NOT NULL DEFAULT 'active',
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sessions (
 token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS auth_tokens (
 token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NULL,kind ENUM('password_reset','wechat_login','wechat_bind') NOT NULL,expires_at DATETIME NOT NULL,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS oauth_accounts (
 provider VARCHAR(20) NOT NULL,provider_uid VARCHAR(190) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,
 PRIMARY KEY(provider,provider_uid), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- ===== 剧本内容与不可变版本：公开内容使用独立快照 =====
CREATE TABLE IF NOT EXISTS scripts (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT UNSIGNED NOT NULL,title VARCHAR(120) NOT NULL,genre VARCHAR(30) NOT NULL,
 tags JSON NOT NULL,synopsis TEXT NOT NULL,config_json JSON NOT NULL,outline MEDIUMTEXT NOT NULL,
 visibility ENUM('private','public') NOT NULL DEFAULT 'private',review_status ENUM('none','pending','approved','rejected') NOT NULL DEFAULT 'none',
 published_json JSON NULL,deleted_at DATETIME NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(owner_id) REFERENCES users(id),INDEX(owner_id,updated_at),INDEX(visibility,review_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS episodes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,script_id BIGINT UNSIGNED NOT NULL,episode_no INT NOT NULL,title VARCHAR(120) NOT NULL,
 document_json JSON NULL,content_html MEDIUMTEXT NOT NULL,content_text MEDIUMTEXT NOT NULL,revision INT NOT NULL DEFAULT 1,
 updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 UNIQUE(script_id,episode_no),FOREIGN KEY(script_id) REFERENCES scripts(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS versions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,episode_id BIGINT UNSIGNED NOT NULL,document_json JSON NULL,content_html MEDIUMTEXT NOT NULL,content_text MEDIUMTEXT NOT NULL,
 revision INT NOT NULL,reason VARCHAR(100) NOT NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 FOREIGN KEY(episode_id) REFERENCES episodes(id) ON DELETE CASCADE,INDEX(episode_id,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- ===== AI 任务、参数与模板 =====
CREATE TABLE IF NOT EXISTS user_ai_settings (
 user_id BIGINT UNSIGNED PRIMARY KEY,key_encrypted TEXT NULL,model VARCHAR(100) NOT NULL,timeout_ms INT UNSIGNED NOT NULL,
 updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- ===== 个人供应商与模型：密钥按账号加密，模型随供应商级联删除 =====
CREATE TABLE IF NOT EXISTS ai_providers (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,
 base_url VARCHAR(500) NOT NULL,api_format VARCHAR(30) NOT NULL DEFAULT 'openai-chat',key_encrypted TEXT NULL,
 enabled BOOLEAN NOT NULL DEFAULT TRUE,timeout_ms INT UNSIGNED NOT NULL DEFAULT 180000,legacy BOOLEAN NOT NULL DEFAULT FALSE,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ai_provider_models (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider_id BIGINT UNSIGNED NOT NULL,model VARCHAR(100) NOT NULL,label VARCHAR(100) NOT NULL,
 enabled BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(provider_id,model),FOREIGN KEY(provider_id) REFERENCES ai_providers(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- ===== 质量报告：保存不可变输入快照、算法版本、分项结果和可定位证据 =====
CREATE TABLE IF NOT EXISTS quality_reports (
 id CHAR(36) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,script_id BIGINT UNSIGNED NOT NULL,job_id CHAR(36) NULL,
 fingerprint CHAR(64) NOT NULL,algorithm_version VARCHAR(30) NOT NULL,model VARCHAR(100) NOT NULL,provider_name VARCHAR(80) NOT NULL,
 status ENUM('running','completed','partial','failed','cancelled') NOT NULL,snapshot_json JSON NOT NULL,result_json JSON NULL,error_code VARCHAR(60) NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(script_id) REFERENCES scripts(id) ON DELETE CASCADE,INDEX(user_id,script_id,created_at),INDEX(fingerprint)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quality_issue_resolutions (
 report_id CHAR(36) NOT NULL,issue_id VARCHAR(40) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(report_id,issue_id),
 FOREIGN KEY(report_id) REFERENCES quality_reports(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS generation_configs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,params JSON NOT NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- 忽略表示作者暂不采纳该报告的问题，独立于已解决状态，不更改客观评分。
CREATE TABLE IF NOT EXISTS quality_issue_ignores (
 report_id CHAR(36) NOT NULL,issue_id VARCHAR(40) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(report_id,issue_id),
 FOREIGN KEY(report_id) REFERENCES quality_reports(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- 每条建议内的不同证据分别记录完成，避免处理一处后整条问题被隐藏。
CREATE TABLE IF NOT EXISTS quality_evidence_resolutions (
 report_id CHAR(36) NOT NULL,issue_id VARCHAR(40) NOT NULL,paragraph_id VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY(report_id,issue_id,paragraph_id),FOREIGN KEY(report_id) REFERENCES quality_reports(id) ON DELETE CASCADE,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ai_jobs (
 id CHAR(36) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,script_id BIGINT UNSIGNED NULL,operation VARCHAR(30) NOT NULL,params JSON NOT NULL,
 status ENUM('running','completed','cancelled','failed') NOT NULL,output MEDIUMTEXT NOT NULL,model VARCHAR(100) NOT NULL,error_code VARCHAR(60) NULL,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS templates (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT UNSIGNED NULL,kind ENUM('official','personal') NOT NULL,visibility ENUM('private','public') NOT NULL DEFAULT 'private',title VARCHAR(120) NOT NULL,genre VARCHAR(30) NOT NULL,
 description TEXT NOT NULL,params JSON NOT NULL,outline MEDIUMTEXT NOT NULL,status ENUM('active','offline') NOT NULL DEFAULT 'active',uses INT NOT NULL DEFAULT 0,
 created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(owner_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS email_codes (
 email VARCHAR(190) NOT NULL,purpose VARCHAR(20) NOT NULL,code_hash CHAR(64) NOT NULL,attempts INT NOT NULL DEFAULT 0,
 sent_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,PRIMARY KEY(email,purpose)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS demo_devices (
 device_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS demo_qr_tickets (
 ticket_hash CHAR(64) PRIMARY KEY,computer_hash CHAR(64) NOT NULL,device_hash CHAR(64) NULL,user_id BIGINT UNSIGNED NULL,
 used BOOLEAN NOT NULL DEFAULT FALSE,expires_at DATETIME NOT NULL,INDEX(expires_at),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- ===== 社区关系：联合主键保证点赞与收藏幂等 =====
CREATE TABLE IF NOT EXISTS likes (user_id BIGINT UNSIGNED NOT NULL,script_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,script_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(script_id) REFERENCES scripts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS favorites (user_id BIGINT UNSIGNED NOT NULL,target_type ENUM('script','template') NOT NULL,target_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,target_type,target_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,script_id BIGINT UNSIGNED NOT NULL,body VARCHAR(1000) NOT NULL,status ENUM('active','hidden') NOT NULL DEFAULT 'active',created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(script_id) REFERENCES scripts(id),INDEX(script_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS browse_history (user_id BIGINT UNSIGNED NOT NULL,script_id BIGINT UNSIGNED NOT NULL,viewed_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,script_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(script_id) REFERENCES scripts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,script_id BIGINT UNSIGNED NOT NULL,submitted_by BIGINT UNSIGNED NOT NULL,snapshot_json JSON NOT NULL,status ENUM('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending',reason VARCHAR(500) NOT NULL DEFAULT '',reviewer_id BIGINT UNSIGNED NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),reviewed_at DATETIME NULL,FOREIGN KEY(script_id) REFERENCES scripts(id),FOREIGN KEY(submitted_by) REFERENCES users(id),FOREIGN KEY(reviewer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,script_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(500) NOT NULL,status ENUM('pending','resolved') NOT NULL DEFAULT 'pending',created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(script_id) REFERENCES scripts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NOT NULL,action VARCHAR(60) NOT NULL,target_id BIGINT UNSIGNED NULL,detail VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS analytics_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(30) NOT NULL,user_id BIGINT UNSIGNED NULL,target_id BIGINT UNSIGNED NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX(event_type,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- ===== AI 实际上游请求：一项多集任务包含多次调用，缺失 usage 使用 NULL =====
CREATE TABLE IF NOT EXISTS ai_requests (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id CHAR(36) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,model VARCHAR(100) NOT NULL,
 phase ENUM('outline','episode','rewrite','evaluation','consistency','verification','planning') NOT NULL,episode_no INT NULL,status ENUM('running','completed','failed','cancelled') NOT NULL,
 prompt_tokens BIGINT UNSIGNED NULL,completion_tokens BIGINT UNSIGNED NULL,total_tokens BIGINT UNSIGNED NULL,prompt_cache_hit_tokens BIGINT UNSIGNED NULL,prompt_cache_miss_tokens BIGINT UNSIGNED NULL,
 elapsed_ms INT UNSIGNED NOT NULL DEFAULT 0,error_code VARCHAR(60) NULL,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),finished_at DATETIME(3) NULL,
 FOREIGN KEY(job_id) REFERENCES ai_jobs(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(created_at,model),INDEX(job_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
